    }
}

class NegativeException extends Exception {
    public NegativeException() { super("Negative input!"); }
    public NegativeException(String msg) { super(msg); }
}
public class Test {
    static void check(int n) throws NegativeException {
        if (n < 0) throw new NegativeException();
    }
    public static void main(String[] args) {
        try {
            check(-1);
        } catch (NegativeException e) {
            System.out.println(e.getMessage());
            System.out.println(e);
        }
    }
}

public class Test {
    public static void main(String[] args) {
        try {
            try {
                throw new RuntimeException("first");
            } catch (RuntimeException e) {
                System.out.print("C:" + e.getMessage() + " ");
                throw new IllegalStateException("second");
            } finally {
                System.out.print("F ");
            }
        } catch (IllegalStateException e) {
            System.out.print("O:" + e.getMessage());
        }
    }
}

